def price_buggy(p, default=10):
    return p or default            # treats a valid 0 as missing
def price_ok(p, default=10):
    return default if p is None else p
print("buggy(0):", price_buggy(0), "| ok(0):", price_ok(0))
class Box:
    def __init__(self, n): self.n = n
    def __len__(self): return self.n   # truthiness falls back to __len__
print("Box(0):", bool(Box(0)), "Box(2):", bool(Box(2)))
